    `severity` ENUM('info', 'success', 'warning', 'error') NOT NULL DEFAULT 'info',
    `title` VARCHAR(255) NOT NULL,
    `body` TEXT DEFAULT NULL,
    `data` JSON DEFAULT NULL,
    `read_at` BIGINT NULL DEFAULT NULL,
    `created_at` BIGINT NOT NULL,
    PRIMARY KEY (`id`),
    KEY `idx_notification_user_read` (`user_id`, `read_at`),
    KEY `idx_notification_user_created` (`user_id`, `created_at`),
    CONSTRAINT `fk_notification_user` FOREIGN KEY (`user_id`) REFERENCES `hilos_user` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Migration: Create hilos_notification_preference table (stub/reference)
-- Copy this SQL to project migration (e.g. 0NN_create_hilos_notification_preference.sql)
--
-- Per-user notification channel preferences (HIL-485). The per-user layer above the
-- global channel configuration (HIL-200): a recipient may opt out of an individual
-- delivery channel (email, telegram, sms, push).
--
-- Sparse opt-out model: a row exists ONLY to record a deviation from the default.
-- No row for a (user, channel) pair means the channel is allowed; a row means the
-- recipient muted that channel. Enabling a channel deletes the row (return to
-- default) rather than storing `enabled = 1`, so "allowed" always means the same
-- thing and the table never needs a row per user x channel on registration, nor a
-- rewrite when a new channel (HIL-199 push, HIL-285 sms) is added.
--
-- A mandatory notification type (NotificationTypeRegistry) bypasses this table and
-- delivers on every globally enabled channel where the recipient has an address.
--
-- user_id points at hilos_user with RESTRICT. Account erasure deletes preference
-- rows in its transaction before the person row. The per-user lookup rides the
-- leftmost prefix of UNIQUE(user_id, channel), so no separate user_id key is needed.

CREATE TABLE `hilos_notification_preference` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `user_id` INT UNSIGNED NOT NULL,
    `channel` VARCHAR(50) NOT NULL,
    `enabled` TINYINT(1) NOT NULL DEFAULT 0,
    `created_at` BIGINT NOT NULL,
    `updated_at` BIGINT NOT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_notification_preference_user_channel` (`user_id`, `channel`),
    CONSTRAINT `fk_notification_preference_user` FOREIGN KEY (`user_id`) REFERENCES `hilos_user` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Migration: Create hilos_push_subscription table (stub/reference)
-- Copy this SQL to project migration (e.g. 0NN_create_hilos_push_subscription.sql)
--
-- Browser push subscriptions per user device (HIL-199). One row is one device's
-- opt-in: the profile section registers the service worker, subscribes through the
-- browser push manager, and sends the endpoint plus its `p256dh` / `auth` keys; the
-- row is the address a push delivery is sent to.
--
-- `endpoint` is the delivery address and is UNIQUE: a re-subscribe (rotated keys, or
-- the same endpoint arriving under a new owner) upserts the one row rather than
-- inserting a duplicate. `endpoint_hash` is the SHA-256 fingerprint the browser can
-- compare without receiving the address. A 404/410 marks `gone_at`; the row remains
-- visible as expired until its owner removes it, while delivery ignores it.
--
-- user_id points at hilos_user with RESTRICT and is indexed for delivery lookup.
-- Account erasure deletes these rows in its transaction. `device_name` is the shared browser/platform
-- label derived from `user_agent`; both it and `last_seen_at` are informational.
-- `revision` is the registration counter: starts at 1, increments on each re-subscription or
-- renewal of the same endpoint, and correlates invalidation reports (`markGoneOwned`) so a
-- delayed gone signal from an older registration does not expire a newer active one.

CREATE TABLE `hilos_push_subscription` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `user_id` INT UNSIGNED NOT NULL,
    `endpoint` VARCHAR(512) NOT NULL,
    `p256dh` VARCHAR(255) NOT NULL,
    `auth` VARCHAR(255) NOT NULL,
    `user_agent` VARCHAR(255) DEFAULT NULL,
    `device_name` VARCHAR(64) DEFAULT NULL,
    `endpoint_hash` CHAR(64) NOT NULL,
    `gone_at` BIGINT NULL DEFAULT NULL,
    `created_at` BIGINT NOT NULL,
    `last_seen_at` BIGINT NULL DEFAULT NULL,
    `revision` BIGINT NOT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_push_subscription_endpoint` (`endpoint`),
    KEY `idx_push_subscription_user` (`user_id`),
    CONSTRAINT `fk_push_subscription_user` FOREIGN KEY (`user_id`) REFERENCES `hilos_user` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Migration: Create hilos_notification_delivery table (stub/reference)
-- Copy this SQL to project migration (e.g. 0NN_create_hilos_notification_delivery.sql)
--
-- Channel delivery of durable notifications (HIL-196). One row is one channel's
